// === Tab: mySketch ===

let kMax;
let step;
let n = 1; // number of blobs
let radius = 50; // diameter of the circle
let inter = 1; // difference between the sizes of two blobs
let maxNoise = 200;

let noiseProg = (x) => (x);


let _p5;
const DEBUG = true;

let Controls, controls;
let playPauseLabel;
let gui;

let cap;
let isRecording = false;
let savedFrames = 0;
let framesToSave = 1000;
let isPlaying = true;




Controls = function() {
  this.saveFrame = function() { save(); }

  this.recordVideo = function() {
    cap.start();
    isRecording = true;
  };

  this.playPause = function() {
    isPlaying = !isPlaying;

    if (isPlaying) {
      playPauseLabel.name('playing');
      loop();
    } else {
      playPauseLabel.name('paused');
      noLoop();
    }
  }
};

function saveVideoFrame() {
  if (isRecording === false) return;

  if (savedFrames === framesToSave) {
    isRecording = false;
    savedFrames = 0;
    cap.stop();
    cap.save();
    return;
  }

  cap.capture(_p5.canvas);
  savedFrames++;
}

function initControls() {
  controls = new Controls();
  window.controls = controls;
  gui = new dat.GUI();
  gui.add(controls, 'saveFrame')
    .name('save frame');
  gui.add(controls, 'recordVideo')
    .name('record video');
  playPauseLabel = gui.add(controls, 'playPause')
    .name('playing');

  cap = new CCapture({ format: 'webm', verbose: true, framerate: 60, name: 'test', quality: 99, display: true});
}
//-----------







function preload(){
	init();
	initControls();
}

function init() {
	window.setTimeout(function(){
		_p5 = createCanvas(windowWidth, windowHeight);
	}, 100);
}




// -----------------------------

function addScript(url, callback){
  script = document.createElement("script");
  script.type = "text/javascript";
	script.crossorigin = 'anonymous';
	script.async = false;
  if(callback){
    if (script.readyState){ /*IE*/
      script.onreadystatechange = function(){
        if (script.readyState == "loaded" || script.readyState == "complete"){
          script.onreadystatechange = null;
          callback(); }
      };
    } else {
      /*Others*/ script.onload = function(){
        callback();
     }
    }
  }
  script.src = url;
  document.head.children[0].appendChild(script);
}









function setup(){
  createCanvas(600, 600);
  //colorMode(HSB, 1);
	angleMode(DEGREES);
  noFill();
	//noLoop();
	kMax = random(0.6, 1.0);
	step = 0.01;
	noStroke();
	drawingContext.shadowBlur = 200;

}

function draw(){
	blendMode(BLEND);
  background(0);
	blendMode(ADD);
  let t = frameCount/200;
  for (let i = n; i > 0; i--) {
		let size = radius + i * inter;
		let k = kMax * sqrt(i/n);
		let noisiness = maxNoise * noiseProg(i / n);

		fill(255, 0, 0, 255);
  	drawingContext.shadowColor = color(255, 255, 0, 255);
    blob(size, width/2, height/2, k, t - i * step, noisiness);

		fill(0, 255, 0, 255);
		drawingContext.shadowColor = color(0, 255, 255, 255);
    blob(size, width/2, height/2, k, t - i * step + 2, noisiness);

		fill(0, 0, 255, 255);
		drawingContext.shadowColor = color(255, 0, 255, 255);
    blob(size, width/2, height/2, k, t - i * step + 4, noisiness);
	saveVideoFrame();
}
}


function blob(size, xCenter, yCenter, k, t, noisiness) {
  beginShape();
	let angleStep = 360 / 8;
  for (let theta = 0; theta <= 360 + 2 * angleStep; theta += angleStep) {
    let r1, r2;
		/*
    if (theta < PI / 2) {
      r1 = cos(theta);
      r2 = 1;
    } else if (theta < PI) {
      r1 = 0;
      r2 = sin(theta);
    } else if (theta < 3 * PI / 2) {
      r1 = sin(theta);
      r2 = 0;
    } else {
      r1 = 1;
      r2 = cos(theta);
    }
		*/
		r1 = cos(theta)+1;
		r2 = sin(theta)+1;
    let r = size + noise(k * r1,  k * r2, t) * noisiness;
    let x = xCenter + r * cos(theta);
    let y = yCenter + r * sin(theta);
    curveVertex(x, y);
  }
  endShape();
}





